insert into public.categories (slug, name, name_so, tagline, tagline_so, description, description_so, cover_image, sort_order) values
  ('herbal', 'Herbal Products', 'Alaabooyinka Dhireed', 'Botanicals, natural ingredients & herbal oils', 'Dhir, walxo dabiici ah & saliidaha dhireed', 'Traditional herbs, pure natural ingredients and nourishing herbal oils, carefully sourced for everyday balance.', 'Dhir dhaqameed, walxo dabiici ah oo saafi ah iyo saliido dhireed oo nafaqeeya, si taxaddar leh loo soo xulay si loo helo dheelitir maalinle ah.', 'ashwagandha.webp', 0),
  ('minerals', 'Minerals', 'Macdano', 'Essential minerals & daily support', 'Macdano muhiim ah & taageero maalinle ah', 'Essential minerals and daily nutritional support — from zinc and iron to omega-3 and collagen.', 'Macdano muhiim ah iyo taageero nafaqo oo maalinle ah — laga bilaabo zinc iyo bir ilaa omega-3 iyo kolajin.', 'ultra-omega-3.webp', 1),
  ('sports', 'Sports Nutrition', 'Nafaqada Isboortiga', 'Creatine, protein & performance', 'Creatine, borotiin & waxqabad', 'Clean, effective nutrition for athletes, gym-goers and active people — creatine, protein, gainers and pre-workouts.', 'Nafaqo nadiif ah oo waxtar leh oo loogu talagalay ciyaartoyda, dadka jimicsiga iyo dadka firfircoon — creatine, borotiin, miisaan-kordhiyeyaal iyo pre-workout.', 'c4-original.webp', 2),
  ('vitamins', 'Vitamins', 'Fitamiinno', 'Everyday vitamins for vitality', 'Fitamiinno maalinle ah oo firfircooni leh', 'High-quality vitamins to support immunity, energy and long-term health.', 'Fitamiinno tayo sare leh oo loogu talagalay taageeridda difaaca jirka, tamarta iyo caafimaadka muddada dheer.', 'c1000.webp', 3)
insert into public.products (slug, name, name_so, brand, aliases, category_id, subcategory, facts, description, description_so, benefits, supplied_benefits, caution, image_labels, price, images, in_stock, is_featured, sort_order) values
  ('ashwagandha-gummies', 'Ashwagandha Gummies', null, 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '1200 mg · 5% withanolides · 180 gummies', 'Vegan ashwagandha gummies made with real fruit juice — an easy way to add this traditional Ayurvedic herb to your daily routine.', 'Xabbado macaan oo vegan ah oo ashwagandha ah, laga sameeyay casiir miro dhab ah — hab fudud oo aad geedkan dhaqameed ee Ayurveda ugu darto nidaamkaaga maalinlaha ah.', '[{"en":"Traditionally used in Ayurveda as an adaptogen to support calm and balance","so":"Dhaqan ahaan Ayurveda waxaa loo isticmaalaa sidii adaptogen si loo taageero degganaanta iyo dheelitirka"},{"en":"Standardised to 5% withanolides, the herb''s key natural compounds","so":"Waxaa lagu habeeyay 5% withanolides, oo ah walxaha dabiiciga ah ee ugu muhiimsan geedka"},{"en":"Vegan, lab-tested gummies — no capsules to swallow","so":"Xabbado vegan ah oo shaybaar lagu baaray — looma baahna kaabsuul la liqo"}]'::jsonb, null, null, null, null, array['ashwagandha.webp']::text[], true, true, 0),
  ('chillflex-herbal-cream-mint', 'ChillFlex Herbal Cream with Mint', null, 'ChillFlex', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '98 g · herbal joint & muscle cream', 'A herbal joint and muscle cream with mint that gives an instant cooling sensation — made for massage after exercise or a long day.', 'Kareem dhireed oo loogu talagalay kalagoysyada iyo murqaha, kana kooban reexaan (mint), kaas oo isla markiiba siiya dareen qabow — loogu talagalay duugis kadib jimicsi ama maalin dheer.', '[{"en":"Mint gives an instant, refreshing cooling sensation","so":"Reexaantu (mint) waxay siisaa dareen qabow oo nafis leh isla markiiba"},{"en":"Smooth cream that massages easily into muscles and joints","so":"Kareem jilicsan oo si fudud loogu duugo murqaha iyo kalagoysyada"},{"en":"Herbal formula for external use only","so":"Isku-dar dhireed oo kaliya dibadda jirka loo isticmaalo"}]'::jsonb, null, null, null, null, array['chillflex-cream.webp']::text[], true, false, 1),
  ('fenugreek', 'Fenugreek', 'Xulbad (Fenugreek)', 'NOW', array['Fengruuk', 'Xulbad', 'Hulbad']::text[], (select id from public.categories where slug = 'herbal'), 'general', '500 mg · 100 veg capsules', 'Fenugreek seed in convenient 500 mg vegetarian capsules — a traditional herb long used in Somali, Middle Eastern and South Asian homes.', 'Iniinta xulbadda oo ku jirta kaabsuul khudradeed oo 500 mg ah — geed dhaqameed muddo dheer laga isticmaali jiray guryaha Soomaalida, Bariga Dhexe iyo Koonfurta Aasiya.', '[{"en":"Traditional herb long valued in Middle Eastern and South Asian herbal practice","so":"Geed dhaqameed oo muddo dheer qiimo ku lahaa daawada dhireed ee Bariga Dhexe iyo Koonfurta Aasiya"},{"en":"Traditionally used to support healthy digestion","so":"Dhaqan ahaan waxaa loo isticmaalaa taageeridda dheefshiid caafimaad qaba"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['fenugreek.webp']::text[], true, false, 2),
  ('magnesium-glycinate', 'Magnesium Glycinate', null, 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '120 capsules', 'Magnesium in its gentle glycinate form — a well-tolerated choice for everyday mineral support.', 'Magnesium oo ku jira qaabka glycinate ee jilicsan — doorasho uu jirku si fiican u qaato oo loogu talagalay taageerada macdanta maalinlaha ah.', '[{"en":"Magnesium contributes to the reduction of tiredness and fatigue","so":"Magnesium-ku wuxuu gacan ka geystaa yaraynta daalka iyo tabar-darrida"},{"en":"Magnesium contributes to normal muscle function","so":"Magnesium-ku wuxuu gacan ka geystaa shaqada caadiga ah ee murqaha"},{"en":"Magnesium contributes to the normal function of the nervous system","so":"Magnesium-ku wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska dareemayaasha"}]'::jsonb, null, null, null, null, array['magnesium-glycinate.webp']::text[], true, true, 3),
  ('prostate-plus', 'Prostate Plus', null, 'Earth''s Creation', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '60 capsules · with saw palmetto', 'A men''s prostate health formula with added saw palmetto, as described by the manufacturer.', 'Isku-dar loogu talagalay caafimaadka qanjirka ''prostate'' ee ragga, oo lagu daray saw palmetto, sida ay shirkadda soo saartay sheegtay.', '[{"en":"Formulated for men''s prostate health, as labelled by the manufacturer","so":"Waxaa loo sameeyay caafimaadka qanjirka ''prostate'' ee ragga, sida shirkaddu ku qortay calaamadda"},{"en":"Contains saw palmetto, a botanical traditionally used in men''s health","so":"Waxaa ku jira saw palmetto, geed dhaqan ahaan loo isticmaalo caafimaadka ragga"},{"en":"Non-GMO dietary supplement made in the USA","so":"Kaab cunto oo aan GMO ahayn, laguna sameeyay Maraykanka"}]'::jsonb, null, '{"en":"Men with urinary or prostate symptoms should see a doctor before use.","so":"Ragga qaba calaamado kaadi ama ''prostate'' la xiriira waa inay dhakhtar arkaan ka hor isticmaalka."}'::jsonb, null, null, array['prostate-plus.webp']::text[], true, false, 4),
  ('shilajit-ultra', 'Shilajit Ultra', null, 'Flynew', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '60 capsules', 'Shilajit in easy capsule form — a mineral-rich resin traditionally gathered from high mountain rocks.', 'Shilajit oo ku jira kaabsuul fudud — xab hodan ku ah macdano, dhaqan ahaan laga soo ururiyo dhagxaanta buuraha dhaadheer.', '[{"en":"Traditional Ayurvedic resin, naturally rich in fulvic acid","so":"Xab dhaqameed Ayurveda ah oo dabiici ahaan hodan ku ah fulvic acid"},{"en":"Easy-to-take capsules — no measuring of resin needed","so":"Kaabsuul si fudud loo qaato — looma baahna in xabka la miisaamo"},{"en":"Made in the USA, as stated on the label","so":"Waxaa lagu sameeyay Maraykanka, sida ku qoran calaamadda"}]'::jsonb, null, null, null, null, array['shilajit-ultra.webp']::text[], true, false, 5),
  ('shilajit-gummies', 'Shilajit Gummies', null, 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '3000 mg · with zinc & vitamin B6 · 60 gummies', 'Berry-flavoured shilajit gummies with added zinc and vitamin B6 — a modern, easy way to enjoy this traditional resin.', 'Xabbado macaan oo shilajit ah oo dhadhan berry leh, lagu daray zinc iyo fitamiin B6 — hab casri ah oo fudud oo lagu isticmaalo xabkan dhaqameed.', '[{"en":"Zinc contributes to the normal function of the immune system","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska difaaca jirka"},{"en":"Vitamin B6 contributes to the reduction of tiredness and fatigue","so":"Fitamiin B6 wuxuu gacan ka geystaa yaraynta daalka iyo tabar-darrida"},{"en":"Vegan, berry-flavoured gummies made in the EU","so":"Xabbado macaan oo vegan ah, dhadhan berry leh, laguna sameeyay Midowga Yurub"}]'::jsonb, null, null, null, null, array['shilajit-gummies.webp']::text[], true, true, 6),
  ('black-cumin', 'Black Cumin Seeds', 'Xabbad Sooda', null, array['Habbat al-Sawda', 'Nigella sativa', 'Xabbad Sooda', 'Habasoodo']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', 'Whole seeds · Nigella sativa', 'Whole Nigella sativa seeds, cherished for generations in Somali and Middle Eastern kitchens and traditional wellness.', 'Xabbad sooda (Nigella sativa) oo dhan, jiil ka jiil qiimo ku lahayd jikada Soomaalida iyo Bariga Dhexe iyo fayo-qabka dhaqameed.', '[{"en":"Whole Nigella sativa seeds with a warm, peppery aroma","so":"Xabbad sooda oo dhan oo leh ur diirran oo basbaas u eg"},{"en":"Traditionally valued in prophetic and Middle Eastern wellness practice","so":"Dhaqan ahaan qiimo weyn ayay ku leedahay tibbiga nabawiga iyo fayo-qabka Bariga Dhexe"},{"en":"Versatile — add to bread, honey, tea or everyday dishes","so":"Siyaabo badan loo isticmaali karo — ku dar rootiga, malabka, shaaha ama cuntada maalinlaha ah"}]'::jsonb, null, null, null, null, array['black-cumin.webp']::text[], true, false, 7),
  ('chia-seeds', 'Chia Seeds', 'Iniinyaha Chia', null, '{}'::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', 'Whole seeds', 'Tiny, nutrient-dense seeds that swell into a soft gel — ideal for puddings, smoothies, yoghurt and juices.', 'Iniinyo yaryar oo nafaqo badan oo biyaha ku bararta oo noqota jel jilicsan — ku fiican macmacaanka, smoothie-ga, caanaha fadhiga iyo casiirka.', '[{"en":"Naturally rich in dietary fibre","so":"Dabiici ahaan hodan ku ah fiber-ka cuntada"},{"en":"Plant source of alpha-linolenic acid (ALA), an omega-3 fatty acid","so":"Il dhireed oo laga helo alpha-linolenic acid (ALA), oo ah dufan omega-3 ah"},{"en":"Easy to add to drinks, porridge and yoghurt","so":"Si fudud loogu dari karo cabbitaannada, boorashka iyo caanaha fadhiga"}]'::jsonb, null, null, null, null, array['chia-seeds.webp']::text[], true, false, 8),
  ('herbal-seeds', 'Herbal Seeds', 'Iniinyo Dhireed', null, '{}'::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'A selection of whole herbal seeds and dried botanicals. Ask our team on WhatsApp for the exact contents of the current selection.', 'Iniinyo dhireed oo dhan iyo dhir la qalajiyay oo la isku daray. Kooxdayada WhatsApp ku weydii waxa saxda ah ee ku jira xulashada hadda jirta.', null, null, null, null, null, array['herbal-seeds.webp']::text[], true, false, 9),
  ('pure-honey', 'Pure Honey', 'Malab Saafi ah', null, array['Malab', 'Honey']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Natural, pure honey with a rich golden colour and flavour — a timeless natural sweetener.', 'Malab dabiici ah oo saafi ah, leh midab dahabi ah iyo dhadhan qani ah — macmacaan dabiici ah oo weligiis qiimo lahaa.', '[{"en":"A natural source of carbohydrates for quick energy","so":"Il dabiici ah oo karbohaydraydh ah oo tamar degdeg ah bixisa"},{"en":"Delicious natural sweetener for tea, porridge and desserts","so":"Macmacaan dabiici ah oo dhadhan fiican leh oo shaaha, boorashka iyo macmacaanka lagu daro"},{"en":"Treasured in traditional and prophetic wellness practice","so":"Qiimo weyn ku leh fayo-qabka dhaqameed iyo tibbiga nabawiga"}]'::jsonb, null, '{"en":"Not suitable for babies under 12 months.","so":"Kuma habboona ilmaha ka yar 12 bilood."}'::jsonb, null, null, array['pure-honey.webp']::text[], true, true, 10),
  ('saffron', 'Saffron', 'Sacfaraan', null, array['Saffron Seeds', 'Sacfaraan', 'Zacfaraan']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', 'Saffron threads', 'Delicate saffron threads with a deep colour and distinctive aroma — a little goes a long way.', 'Xarigo sacfaraan oo jilicsan, leh midab qoto dheer iyo ur gaar ah — wax yar ayaa ku filan.', '[{"en":"Prized spice that adds a rich golden colour and aroma","so":"Xawaash qaali ah oo siiya midab dahabi ah iyo ur fiican"},{"en":"A few threads are enough to flavour rice, tea and desserts","so":"Dhowr xarig ayaa ku filan in lagu dhadhamiyo bariiska, shaaha iyo macmacaanka"},{"en":"Long valued in traditional Middle Eastern and Persian practice","so":"Muddo dheer ayuu qiimo ku lahaa dhaqanka Bariga Dhexe iyo Faaris"}]'::jsonb, null, null, null, null, array['saffron.webp']::text[], true, false, 11),
  ('cloves', 'Cloves', 'Qaranfuul', null, '{}'::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Whole aromatic cloves for tea, rice, and traditional Somali dishes. Ask our team on WhatsApp for details of the current stock.', 'Qaranfuul udgoon oo dhan oo loogu talagalay shaaha, bariiska iyo cuntooyinka dhaqameed ee Soomaalida. Kooxdayada WhatsApp ku weydii faahfaahinta kaydka hadda jira.', '[{"en":"Adds warm, rich aroma to tea, rice and stews","so":"Shaaha, bariiska iyo maraqa wuxuu siiyaa ur diiran oo qani ah"},{"en":"Naturally contains eugenol, an aromatic plant compound","so":"Si dabiici ah wuxuu ka kooban yahay eugenol, walax udgoon oo dhir ah"},{"en":"Long used in traditional home remedies and cooking","so":"Muddo dheer ayaa loo isticmaalay daawooyinka guriga iyo karinta dhaqameed"}]'::jsonb, null, null, null, null, array['star-anise.webp']::text[], true, false, 12),
  ('batana-oil', 'Batana Oil', null, 'Hualijia', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'oils', '120 g · scalp & hair oil', 'A rich scalp and hair oil made with batana oil, traditionally used by the Miskito people of Honduras for hair care.', 'Saliid timo iyo madax oo qani ah oo laga sameeyay saliidda batana, dhaqan ahaan ay dadka Miskito ee Honduras u isticmaalaan daryeelka timaha.', '[{"en":"Rich, nourishing oil that conditions dry hair","so":"Saliid qani ah oo nafaqeysa, qoyana timaha qalalan"},{"en":"Helps soften hair and reduce the look of split ends","so":"Waxay gacan ka geysataa jilcinta timaha iyo yaraynta muuqaalka darfaha jaban"},{"en":"Massage into the scalp as part of a regular hair-care routine","so":"Ku duug maqaarka madaxa qayb ka mid ah daryeelka timaha ee joogtada ah"}]'::jsonb, null, null, null, null, array['batana-oil.webp']::text[], true, true, 13),
  ('feg-hair-spray', 'FEG Hair Spray', null, 'FEG', array['Feg Oil']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '50 ml spray', 'A scalp spray from FEG used as part of a hair-care routine. Ask our team for full ingredient and usage details.', 'Buufin madaxa ah oo ka timid FEG, loo isticmaalo qayb ka mid ah daryeelka timaha. Kooxdayada weydii faahfaahinta buuxda ee walxaha iyo isticmaalka.', null, null, null, null, null, array['feg-hair-spray.webp']::text[], true, false, 14),
  ('minoxidil-5', 'Minoxidil 5% Topical Solution', null, 'Kirkland Signature', array['Minoxidile']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '60 ml · 1-month supply · men', 'Extra-strength 5% minoxidil topical solution for men — an over-the-counter hair regrowth treatment for hereditary hair loss on the top of the scalp.', 'Dareere minoxidil 5% ah oo xoog badan oo loogu talagalay ragga — daawo aan warqad dhakhtar u baahnayn oo loo isticmaalo soo celinta timaha ka dhacay sababo hideed dhinaca sare ee madaxa.', '[{"en":"Contains 5% minoxidil, a clinically studied hair-regrowth ingredient","so":"Waxaa ku jira 5% minoxidil, walax si caafimaad ah loo daraaseeyay oo loogu talagalay soo celinta timaha"},{"en":"For hereditary hair thinning at the top of the scalp in men","so":"Loogu talagalay khafiifinta timaha ee hidaha ah ee dhinaca sare ee madaxa ragga"},{"en":"Unscented solution for daily use on the scalp","so":"Dareere aan ur lahayn oo maalin walba madaxa la mariyo"}]'::jsonb, null, '{"en":"Medicine for external use only. For men, as stated on the label. Speak to a pharmacist or doctor first if you have a heart condition or other health concerns.","so":"Daawo dibadda jirka oo keliya loo isticmaalo. Ragga ayaa loogu talagalay, sida ku qoran calaamadda. Marka hore la hadal farmashiiste ama dhakhtar haddii aad qabto xanuun wadne ama walaac kale oo caafimaad."}'::jsonb, null, null, array['minoxidil.webp']::text[], true, false, 15),
  ('rosemary-oil', 'Natural Rosemary Oil', 'Saliidda Rosemary', 'Nature Spell', array['Rosmery Oil']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '150 ml · hair & body oil', 'A natural treatment oil infused with rosemary, suitable for all hair and skin types.', 'Saliid dabiici ah oo lagu qasay rosemary, ku habboon dhammaan noocyada timaha iyo maqaarka.', '[{"en":"Conditions and adds shine to all hair types","so":"Waxay qoysaa oo dhalaal siisaa dhammaan noocyada timaha"},{"en":"Can be massaged into the scalp as part of a hair-care routine","so":"Waa lagu duugi karaa maqaarka madaxa qayb ka mid ah daryeelka timaha"},{"en":"Doubles as a nourishing body oil for skin","so":"Waxaa sidoo kale loo isticmaali karaa saliid jirka ah oo maqaarka nafaqeysa"}]'::jsonb, null, null, null, null, array['rosemary-oil.webp']::text[], true, false, 16),
  ('saliida-mucjisada', 'Saliida Mucjisada', 'Saliida Mucjisada', 'Somwell', array['Miracle Oil', 'Saliidda Mucjisada']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '300 ml · body massage oil spray', 'Somwell Miracle Oil — a relaxation body massage oil spray.', 'Somwell Miracle Oil — buufin saliid duugis jirka ah oo nasasho leh.', null, '[{"en":"Treats back pain, bone pain, headaches, fainting, and nerve issues — and the Holy Quran.","so":"Waxay daawaysaa xanuunka dhabarka, xanuunka lafaha, madax-xanuunka, suuxdinta, iyo dhibaatooyinka dareemayaasha — iyo Quraanka Kariimka ah."}]'::jsonb, null, null, null, array['saliida-mucjisada.webp']::text[], true, true, 17),
  ('saytuun-oil', 'Saytuun Oil (Extra Virgin Olive Oil)', 'Saliidda Saytuunka', 'Bestolio', array['Olive oil', 'Saytuun']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '100% extra virgin · first cold pressed · several sizes', '100% extra virgin olive oil, first cold pressed, with a great rich flavour — available in several bottle sizes.', 'Saliid saytuun 100% extra virgin ah, tuujin qabow oo koowaad ah, leh dhadhan qani ah — waxaa la helaa dhowr cabbir oo dhalo ah.', '[{"en":"Rich in monounsaturated fats (oleic acid)","so":"Hodan ku ah dufanka monounsaturated (oleic acid)"},{"en":"First cold pressed to keep its full natural flavour","so":"Tuujin qabow oo koowaad ah si dhadhankeeda dabiiciga ah loo ilaaliyo"},{"en":"Ideal for salads, cooking and traditional hair and skin care","so":"Ku fiican saladhka, karinta iyo daryeelka dhaqameed ee timaha iyo maqaarka"}]'::jsonb, null, null, null, null, array['saytuun-oil.webp']::text[], true, false, 18),
  ('collagen-beauty-gummies', 'Collagen Beauty Gummies', 'Kolajin (Collagen) Gummies', 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, 'Hydrolysed bovine collagen I & III · vitamin C, folic acid & biotin · 60 gummies', 'Strawberry-flavoured gummies with hydrolysed collagen, vitamin C, folic acid and biotin for your daily beauty routine.', 'Xabbado macaan oo dhadhan istroberi leh oo ka kooban kolajin la jajabiyay, fitamiin C, folic acid iyo biotin, loogu talagalay quruxda maalinlaha ah.', '[{"en":"Vitamin C contributes to normal collagen formation for healthy skin","so":"Fitamiin C wuxuu gacan ka geystaa samaynta caadiga ah ee kolajinka si maqaarku u caafimaad qabo"},{"en":"Biotin contributes to the maintenance of normal hair and skin","so":"Biotin-ku wuxuu gacan ka geystaa ilaalinta timo iyo maqaar caadi ah"},{"en":"Hydrolysed bovine collagen types I & III in a tasty gummy","so":"Kolajin lo''aad (nooca I & III) oo la jajabiyay, ku jira xabbad macaan"}]'::jsonb, null, null, null, null, array['collagen.webp']::text[], true, true, 19),
  ('dhea-25', 'DHEA 25 mg', null, 'Earth''s Creation', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, '25 mg per serving · 60 capsules', 'DHEA (dehydroepiandrosterone), 25 mg per serving — a hormone precursor that the body''s adrenal glands naturally produce.', 'DHEA (dehydroepiandrosterone), 25 mg qaadasho kasta — hormoon ay qanjirada adrenal-ka ee jirku si dabiici ah u sameeyaan.', '[{"en":"DHEA is a hormone naturally produced by the adrenal glands","so":"DHEA waa hormoon ay dabiici ahaan sameeyaan qanjirada adrenal-ka"},{"en":"Provides 25 mg of DHEA per serving","so":"Qaadasho kasta waxay bixisaa 25 mg oo DHEA ah"},{"en":"Non-GMO capsules made in the USA","so":"Kaabsuul aan GMO ahayn oo lagu sameeyay Maraykanka"}]'::jsonb, null, '{"en":"DHEA is a hormone. Use only after speaking with a doctor. Not for under-18s or for pregnant or breastfeeding women.","so":"DHEA waa hormoon. Isticmaal oo keliya kadib markaad la hadasho dhakhtar. Looma talagelin dadka ka yar 18 sano ama haweenka uurka leh ama naas-nuujinaya."}'::jsonb, null, null, array['dhea.webp']::text[], true, false, 20),
  ('inositol-capsules', 'Inositol Capsules 500 mg', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, '500 mg · myo-inositol · 100 veg capsules', 'Inositol in its natural myo-inositol form, in 500 mg vegetarian capsules.', 'Inositol oo ku jira qaabkiisa dabiiciga ah ee myo-inositol, kaabsuul khudradeed oo 500 mg ah.', '[{"en":"Provides myo-inositol, the most common natural form of inositol","so":"Wuxuu bixiyaa myo-inositol, qaabka dabiiciga ah ee ugu badan ee inositol"},{"en":"Supports healthy cell membrane function, as labelled","so":"Wuxuu taageeraa shaqada caafimaadka qabta ee xuubka unugyada, sida ku qoran calaamadda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['inositol.webp']::text[], true, false, 21),
  ('iron-complex', 'Iron Complex', 'Bir (Iron Complex)', 'NOW', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, '100 tablets · bioavailable iron', 'A bioavailable, gentle iron complex — an essential mineral for everyday energy.', 'Isku-dar bir ah oo jirku si fiican u nuugo oo jilicsan — macdan muhiim u ah tamarta maalinlaha ah.', '[{"en":"Iron contributes to the normal formation of red blood cells and haemoglobin","so":"Birtu waxay gacan ka geysataa samaynta caadiga ah ee unugyada dhiigga cas iyo haemoglobin-ka"},{"en":"Iron contributes to normal oxygen transport in the body","so":"Birtu waxay gacan ka geysataa qaadista caadiga ah ee ogsijiinta jirka"},{"en":"Iron contributes to the reduction of tiredness and fatigue","so":"Birtu waxay gacan ka geysataa yaraynta daalka iyo tabar-darrida"}]'::jsonb, null, '{"en":"Keep out of reach of children — too much iron is dangerous for young children.","so":"Ka fogee carruurta — bir badan ayaa khatar ku ah carruurta yaryar."}'::jsonb, null, null, array['iron-complex.webp']::text[], true, false, 22),
  ('ultra-omega-3', 'Ultra Omega-3 Fish Oil', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, '500 EPA / 250 DHA · 90 softgels', 'Concentrated fish oil with 500 mg EPA and 250 mg DHA in odour-controlled, enteric-coated softgels.', 'Saliid kalluun oo xoogan oo leh 500 mg EPA iyo 250 mg DHA, ku jira kaabsuul jilicsan oo urta la xakameeyay oo dahaar caloosha ilaaliya leh.', '[{"en":"EPA and DHA contribute to the normal function of the heart","so":"EPA iyo DHA waxay gacan ka geystaan shaqada caadiga ah ee wadnaha"},{"en":"DHA contributes to the maintenance of normal brain function","so":"DHA wuxuu gacan ka geystaa ilaalinta shaqada caadiga ah ee maskaxda"},{"en":"Odour-controlled, enteric-coated softgels","so":"Kaabsuul jilicsan oo urta la xakameeyay, dahaar caloosha ilaaliya leh"}]'::jsonb, null, null, null, null, array['ultra-omega-3.webp']::text[], true, true, 23),
  ('zinc-50', 'Zinc 50 mg', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, '50 mg · 100 tablets', 'Essential zinc in 50 mg tablets for everyday immune and enzyme support.', 'Zinc muhiim ah oo ku jira kiniin 50 mg ah, loogu talagalay taageerada maalinlaha ah ee difaaca jirka iyo enzymes-ka.', '[{"en":"Zinc contributes to the normal function of the immune system","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska difaaca jirka"},{"en":"Zinc contributes to normal enzyme function and metabolism","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee enzymes-ka iyo dheef-shiid kiimikaadka"},{"en":"Zinc contributes to the maintenance of normal skin, hair and nails","so":"Zinc-gu wuxuu gacan ka geystaa ilaalinta maqaar, timo iyo ciddiyo caadi ah"}]'::jsonb, null, null, null, null, array['zinc.webp']::text[], true, false, 24),
  ('zinc-picolinate', 'Zinc Picolinate 50 mg', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'minerals'), null, '50 mg · 40 veg capsules', 'Zinc in picolinate form, a chelated zinc, in 50 mg vegetarian capsules.', 'Zinc oo ku jira qaabka picolinate (zinc chelated ah), kaabsuul khudradeed oo 50 mg ah.', '[{"en":"Zinc contributes to the normal function of the immune system","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska difaaca jirka"},{"en":"Zinc contributes to the maintenance of normal skin","so":"Zinc-gu wuxuu gacan ka geystaa ilaalinta maqaar caadi ah"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['zinc-picolinate.webp']::text[], true, false, 25),
  ('cell-tech', 'Cell-Tech Creatine', null, 'MuscleTech', array['Cell Tech']::text[], (select id from public.categories where slug = 'sports'), null, 'Fruit punch · 2.27 kg', 'MuscleTech''s creatine formula with carbohydrates, made for strength-focused training.', 'Isku-darka creatine ee MuscleTech oo lagu daray karbohaydraydh, loogu talagalay tababarka xoogga.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Combines creatine with carbohydrates for use after training","so":"Wuxuu isku daraa creatine iyo karbohaydraydh si loo isticmaalo kadib tababarka"},{"en":"Fruit punch flavoured powder that mixes easily with water","so":"Budo dhadhan fruit punch leh oo si fudud biyo ugu milma"}]'::jsonb, null, null, null, null, array['cell-tech.webp']::text[], true, false, 26),
  ('creatine-micronized', 'Creatine Monohydrate Micronized', null, 'Applied Nutrition', array['Creatine Micronized']::text[], (select id from public.categories where slug = 'sports'), null, '100% creatine monohydrate · unflavoured', '100% micronised creatine monohydrate from Applied Nutrition Professional, tested for athletes.', 'Creatine monohydrate 100% ah oo la jilciyay (micronised) oo ka yimid Applied Nutrition Professional, loona baaray ciyaartoyda.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Micronised powder for smooth, easy mixing","so":"Budo la jilciyay oo si siman oo fudud u milma"},{"en":"Unflavoured — add to any shake or drink","so":"Dhadhan ma laha — ku dar cabbitaan kasta ama shake"}]'::jsonb, null, null, null, null, array['creatine-micronized.webp']::text[], true, false, 27),
  ('creatine-monohydrate', 'Creatine Monohydrate', null, null, '{}'::text[], (select id from public.categories where slug = 'sports'), null, 'Creatine monohydrate powder', 'Classic creatine monohydrate powder — a staple for strength and power training.', 'Budada creatine monohydrate ee caadiga ah — asaas u ah tababarka xoogga iyo awoodda.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Pure creatine monohydrate powder","so":"Budo creatine monohydrate ah oo saafi ah"},{"en":"Easy to add to water, juice or protein shakes","so":"Si fudud loogu dari karo biyaha, casiirka ama shake-ga borotiinka"}]'::jsonb, null, null, null, null, array['creatine-monohydrate.webp']::text[], true, false, 28),
  ('creatine-monohydrate-icy-blue-razz', 'Creatine Monohydrate — Icy Blue Razz', null, 'Applied Nutrition', array['Creatine Monohydrtae', 'Juicy flavours']::text[], (select id from public.categories where slug = 'sports'), null, 'Micronised · Icy Blue Razz · 50 servings', 'Micronised creatine monohydrate with a juicy Icy Blue Razz flavour, from Applied Nutrition.', 'Creatine monohydrate la jilciyay oo leh dhadhanka macaan ee Icy Blue Razz, kana yimid Applied Nutrition.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Juicy Icy Blue Razz flavour — 50 servings","so":"Dhadhan macaan oo Icy Blue Razz ah — 50 qaadasho"},{"en":"Tested for athletes and approved by the Vegetarian Society","so":"Loo baaray ciyaartoyda, waxaana ansixiyay Vegetarian Society"}]'::jsonb, null, null, null, null, array['creatine-monohydrate-icy-blue.webp']::text[], true, false, 29),
  ('iso100-dunkin-glazed-donut', 'ISO100 Dunkin'' Glazed Donut Protein', null, 'Dymatize', array['Dunkin', 'Protein tub', 'Whey']::text[], (select id from public.categories where slug = 'sports'), null, '25 g protein · 5.5 g BCAAs · 910 g · 20 servings', 'Dymatize ISO100 hydrolysed whey protein isolate in Dunkin'' Glazed Donut flavour.', 'Dymatize ISO100 — borotiin whey isolate ah oo la jajabiyay, leh dhadhanka Dunkin'' Glazed Donut.', '[{"en":"Protein contributes to the growth and maintenance of muscle mass","so":"Borotiinku wuxuu gacan ka geystaa korriinka iyo ilaalinta cufnaanta murqaha"},{"en":"25 g of protein per serving from hydrolysed whey protein isolate","so":"25 g oo borotiin ah qaadasho kasta, oo ka yimid whey protein isolate la jajabiyay"},{"en":"Dessert-style Dunkin'' Glazed Donut flavour","so":"Dhadhan macmacaan u eg oo Dunkin'' Glazed Donut ah"}]'::jsonb, null, null, null, null, array['iso100-dunkin.webp']::text[], true, true, 30),
  ('gold-creatine', 'Gold Creatine', null, 'Kevin Levrone', '{}'::text[], (select id from public.categories where slug = 'sports'), null, '300 g · unflavoured', 'Unflavoured creatine powder from the Kevin Levrone Signature Series Gold Line.', 'Budo creatine ah oo aan dhadhan lahayn oo ka tirsan Kevin Levrone Signature Series Gold Line.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Unflavoured powder for mixing and stacking","so":"Budo aan dhadhan lahayn oo lagu qasi karo kaabayaal kale"},{"en":"Part of the Kevin Levrone Signature Series","so":"Qayb ka mid ah Kevin Levrone Signature Series"}]'::jsonb, null, null, null, null, array['gold-creatine.webp']::text[], true, false, 31),
  ('l-citrulline', 'L-Citrulline 750 mg', null, 'NOW', array['L- Citruline']::text[], (select id from public.categories where slug = 'sports'), null, '750 mg · 90 veg capsules', 'Free-form L-citrulline in 750 mg vegetarian capsules — a popular amino acid in sports nutrition.', 'L-citrulline xor ah oo ku jira kaabsuul khudradeed oo 750 mg ah — amino acid caan ka ah nafaqada isboortiga.', '[{"en":"Free-form L-citrulline, a naturally occurring amino acid","so":"L-citrulline xor ah, oo ah amino acid dabiici ahaan jira"},{"en":"Involved in the body''s urea cycle and protein metabolism, as labelled","so":"Wuxuu door ku leeyahay wareegga urea iyo dheef-shiidka borotiinka, sida ku qoran calaamadda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['l-citrulline.webp']::text[], true, false, 32),
