  ('usn-pure-creatine', 'Pure Creatine Monohydrate', null, 'USN', array['Pure Creatine']::text[], (select id from public.categories where slug = 'sports'), null, '256 g · monohydrate powder', 'USN Pure Creatine monohydrate powder for strength and stamina training.', 'Budada creatine monohydrate ee USN Pure, loogu talagalay tababarka xoogga iyo adkeysiga.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Pure creatine monohydrate powder, unflavoured","so":"Budo creatine monohydrate ah oo saafi ah, aan dhadhan lahayn"},{"en":"Easy to add to water, juice or protein shakes","so":"Si fudud loogu dari karo biyaha, casiirka ama shake-ga borotiinka"}]'::jsonb, null, null, null, null, array['pure-creatine.webp']::text[], true, false, 37),
